<?php $token = (string)($_GET['token'] ?? ''); $csrf = \App\Security::getCsrfToken(); ?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Xác thực đơn nghỉ</title><link rel="stylesheet" href="assets/css/main.css?v=<?= time() ?>"></head><body><div class="app-container"><main class="search-wrapper leave-shell"><div class="search-top"><aside class="search-left leave-aside"><div class="search-brand"><div class="search-brand-logo">NP</div><h1 class="search-brand-title">Xác thực đơn nghỉ</h1><p class="search-brand-desc">Đăng nhập tài khoản của bạn để xác nhận đơn trước khi gửi quản lý duyệt.</p></div></aside><section class="search-right"><div class="leave-kicker">Liên kết bảo mật</div><h2 class="search-right-title">Xác nhận đơn nghỉ</h2><p class="search-right-sub">Link chỉ dùng một lần và có hiệu lực trong 24 giờ.</p><form id="verify-form"><div class="form-group"><label class="form-label">Mã nhân viên</label><input class="form-input" name="verifier_id" required autocomplete="off"></div><div class="form-group leave-gap"><label class="form-label">Mật khẩu</label><input class="form-input" type="password" name="verifier_password" required autocomplete="current-password"></div><button class="btn-submit leave-submit" type="submit">Xác nhận đơn</button></form><div id="verify-result" class="leave-feedback" aria-live="polite"></div></section></div></main></div><script>const token=<?= json_encode($token) ?>,csrf=<?= json_encode($csrf) ?>;document.getElementById('verify-form').addEventListener('submit',async e=>{e.preventDefault();const out=document.getElementById('verify-result'),f=new FormData(e.target);f.append('action','leave_confirm_share');f.append('token',token);f.append('csrf_token',csrf);try{const j=await fetch('index.php',{method:'POST',body:f}).then(r=>r.json());out.className='leave-feedback '+(j.success?'is-success':'is-error');out.textContent=j.message;if(j.success)e.target.remove()}catch(_){out.className='leave-feedback is-error';out.textContent='Không thể xác thực. Vui lòng thử lại.'}});</script></body></html>
